@Component("adSlot-handler")
@ProcessingGroup("adSlot-processing-group")
public class AdSlotEventHandler {
	
	// core constructor
	AdSlotEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateAdSlotEvent
     */
    @EventHandler
    public void handle( CreateAdSlotEvent event) {
        entityManager.persist(new AdSlot(event.getAdSlotId(), event.getSlotCode(), event.getWidth(), event.getHeight(), event.getFloorPrice(), event.getInventorySource(), event.getPlacements(), event.getRates(), event.getFormat()));
    }

    /*
     * @param	event UpdateAdSlotEvent
     */
    @EventHandler
    public AdSlot handle( UpdateAdSlotEvent event) {
    	entityManager.merge(new AdSlot(event.getAdSlotId(), event.getSlotCode(), event.getWidth(), event.getHeight(), event.getFloorPrice(), event.getInventorySource(), event.getPlacements(), event.getRates(), event.getFormat()));
    }
    
    /*
     * @param	event DeleteAdSlotEvent
     */
    @EventHandler
    public void on( DeleteAdSlotEvent event) {
    	AdSlot entity = new AdSlot();
   
    	// ------------------------------------------
    	// apply the AdSlotId
    	// ------------------------------------------
    	entity.setAdSlotId( event.getAdSlotId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final AdSlotRepository adSlotEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(AdSlotEventHandler.class.getName());

}
